"use client";

import { useState } from "react";
import { ChevronLeft, ChevronRight, Plus, X, Clock } from "lucide-react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, isSameDay, addDays } from "date-fns";
import { nl } from "date-fns/locale"; 
import { createCalendarItem } from "@/app/actions/task-actions"; 
import { useRouter } from "next/navigation";

export default function CalendarClient({ initialTasks }: { initialTasks: any[] }) {
  const router = useRouter();
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [loading, setLoading] = useState(false);
  const [title, setTitle] = useState("");
  const [type, setType] = useState("agenda");
  
  // YENİ: Saat State'leri
  const [startTime, setStartTime] = useState("09:00");
  const [endTime, setEndTime] = useState("10:00");

  // Verileri eşleme (Timezone hatasını önlemek için new Date kullanıyoruz)
  const taskMap = initialTasks.reduce((acc: any, item) => {
    if (item.startDatetime) {
      const dateKey = format(new Date(item.startDatetime), "yyyy-MM-dd");
      if (!acc[dateKey]) acc[dateKey] = [];
      acc[dateKey].push(item);
    }
    return acc;
  }, {});

  const handleSave = async () => {
    if (!title || !selectedDate) return;
    setLoading(true);

    const payload = {
      titel: title,
      documentType: type,
      datum: format(selectedDate, "yyyy-MM-dd"),
      startTime: startTime, // Seçilen başlangıç saati
      endTime: endTime      // Seçilen bitiş saati
    };

    try {
      const res = await createCalendarItem(payload);
      if (res.success) {
        setTitle("");
        setSelectedDate(null);
        router.refresh(); 
        window.location.reload(); 
      } else {
        alert("Fout: " + res.error);
      }
    } catch (err) {
      console.error("Fout:", err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-[1600px] mx-auto px-4 py-10 relative">
      
      {/* HEADER (Eski Tasarımın) */}
      <div className="flex justify-between items-center mb-12 border-b border-white/5 pb-10">
        <div>
          <h1 className="text-6xl font-black text-white italic tracking-tighter uppercase leading-none drop-shadow-2xl">Temporal Grid</h1>
          <p className="text-fuchsia-500 text-[10px] font-bold tracking-[0.7em] uppercase mt-3">Systeem Status: Actief</p>
        </div>
        
        <div className="flex items-center gap-6 bg-[#0a0e17]/80 border border-white/10 p-3 rounded-2xl backdrop-blur-xl shadow-2xl text-white">
          <button onClick={() => setCurrentMonth(subMonths(currentMonth, 1))} className="p-3 hover:text-fuchsia-500 text-teal-500 transition-all cursor-pointer"><ChevronLeft size={28} /></button>
          <span className="text-xl font-black w-56 text-center uppercase tracking-[0.2em] italic">{format(currentMonth, "MMMM yyyy", { locale: nl })}</span>
          <button onClick={() => setCurrentMonth(addMonths(currentMonth, 1))} className="p-3 hover:text-fuchsia-500 text-teal-500 transition-all cursor-pointer"><ChevronRight size={28} /></button>
        </div>
      </div>

      {/* TAKVİM GRID */}
      <div className="bg-[#0a0e17]/90 border border-white/10 rounded-[40px] overflow-hidden shadow-2xl backdrop-blur-3xl">
        <div className="grid grid-cols-7 bg-white/5 py-6 border-b border-white/10 text-center font-black text-teal-500/40 text-[11px] uppercase tracking-[0.5em]">
          {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map(d => <span key={d}>{d}</span>)}
        </div>

        <div className="grid grid-cols-7">
          {(() => {
            const days = [];
            let day = startOfWeek(startOfMonth(currentMonth), { weekStartsOn: 1 });
            const endDate = endOfWeek(endOfMonth(currentMonth), { weekStartsOn: 1 });

            while (day <= endDate) {
              const dateKey = format(day, "yyyy-MM-dd");
              const dayTasks = taskMap[dateKey] || [];
              const isCurrentMonth = isSameMonth(day, currentMonth);
              const isToday = isSameDay(day, new Date());
              const currentDay = day;

              days.push(
                <div 
                  key={day.toString()} 
                  onClick={() => setSelectedDate(currentDay)}
                  className={`min-h-[170px] border border-white/5 p-5 transition-all cursor-pointer hover:bg-fuchsia-500/[0.03] relative group ${!isCurrentMonth ? "opacity-5 pointer-events-none" : "opacity-100"}`}
                >
                  <span className={`text-sm font-mono mb-3 block ${isToday ? "text-fuchsia-500 font-black scale-125" : "text-teal-500/20"}`}>{format(day, "d")}</span>
                  <div className="space-y-2">
                    {dayTasks.map((t: any) => (
                      <div key={t.id} className={`text-[10px] px-3 py-2 rounded-xl border font-bold uppercase tracking-tighter ${
                        t.description === 'agenda' || t.description === 'assignment' ? 'bg-blue-600/10 border-blue-500/30 text-blue-400' : 'bg-fuchsia-600/10 border-fuchsia-500/30 text-fuchsia-400'
                      }`}>
                        <div className="flex justify-between items-center">
                          <span className="truncate">{t.title}</span>
                          <span className="text-[8px] opacity-60 ml-1">
                            {format(new Date(t.startDatetime), "HH:mm")}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                  <div className="absolute bottom-5 right-5 opacity-0 group-hover:opacity-100 transition-all"><Plus size={18} className="text-fuchsia-500" /></div>
                </div>
              );
              day = addDays(day, 1);
            }
            return days;
          })()}
        </div>
      </div>

      {/* MODAL (ZAMAN ARALIKLI) */}
      {selectedDate && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#02040a]/95 backdrop-blur-xl px-4">
          <div className="bg-[#0E153A] border border-fuchsia-500/40 p-12 rounded-[40px] w-full max-w-lg shadow-2xl relative">
            <button onClick={() => setSelectedDate(null)} className="absolute top-8 right-8 text-white/20 hover:text-white cursor-pointer"><X size={32} /></button>
            
            <div className="mb-10">
              <h3 className="text-fuchsia-500 font-black uppercase text-[11px] tracking-[0.6em] mb-4">Toevoegen Aan Tijdlijn</h3>
              <p className="text-4xl font-black text-white italic tracking-tighter uppercase">{format(selectedDate, "dd MMMM yyyy", { locale: nl })}</p>
            </div>

            <div className="space-y-8">
              {/* Başlık */}
              <input 
                autoFocus value={title} onChange={(e) => setTitle(e.target.value)}
                className="w-full bg-[#070B24] border border-white/10 p-6 text-white font-bold focus:border-fuchsia-500 outline-none rounded-2xl text-lg"
                placeholder="Bijv. Deadline Project..."
              />

              {/* iPHONE STİLİ SAAT SEÇİCİLER */}
              <div className="bg-[#070B24] border border-white/10 rounded-2xl divide-y divide-white/5">
                <div className="flex justify-between items-center p-5">
                  <span className="text-teal-500/40 text-[11px] font-black uppercase tracking-widest flex items-center gap-2"><Clock size={14}/> Starttijd</span>
                  <input type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)} className="bg-[#0E153A] text-white p-2 rounded-lg font-mono outline-none border border-white/5" />
                </div>
                <div className="flex justify-between items-center p-5">
                  <span className="text-teal-500/40 text-[11px] font-black uppercase tracking-widest flex items-center gap-2"><Clock size={14}/> Eindtijd</span>
                  <input type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)} className="bg-[#0E153A] text-white p-2 rounded-lg font-mono outline-none border border-white/5" />
                </div>
              </div>

              {/* Kategoriler */}
              <div className="grid grid-cols-2 gap-4">
                {['agenda', 'assignment', 'meeting', 'daily'].map((cat) => (
                  <button key={cat} onClick={() => setType(cat)} className={`py-4 text-[10px] font-black uppercase border transition-all rounded-xl ${type === cat ? 'bg-fuchsia-600 border-fuchsia-600 text-white shadow-lg' : 'bg-[#070B24] border-white/5 text-white/30'}`}>
                    {cat}
                  </button>
                ))}
              </div>

              <button 
                onClick={handleSave} disabled={loading || !title}
                className="w-full bg-white text-[#0E153A] font-black py-6 mt-4 hover:bg-fuchsia-500 hover:text-white transition-all uppercase text-sm tracking-[0.5em] rounded-[24px]"
              >
                {loading ? "Verwerken..." : "Bevestigen"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}